from taf.gnb.oam.coam.vdu.releases.vduoam23r1 import vDuOAM23R1
from taf.gnb.oam.coam.vdu.schemas.asm.get_mhas_diff_v1 import GetMHAsDiffV1
from taf.gnb.oam.coam.vdu.schemas.asm.get_raes_diff_v1 import GetRAEsDiffV1
from taf.gnb.oam.coam.vdu.schemas.asm.get_rets_diff_v1 import GetRETsDiffV1
from taf.gnb.oam.coam.vdu.schemas.asm.lock_slicing_operation_resp_v1 import (
    LockSlicingOperationRespV1,
)
from taf.gnb.oam.coam.vdu.schemas.asm.network_slicing_diff_v1 import NetworkSlicing
from taf.gnb.oam.coam.vdu.schemas.asm.revert_object_resp_v1 import (
    RevertObjectResponseV1,
)
from taf.gnb.oam.coam.vdu.schemas.asm_licensed.get_alds_response_v1 import (
    GetAldsResponseV1,
)
from taf.gnb.oam.coam.vdu.schemas.asm_licensed.rad_debug_param_update_response import (
    RadDebugParamUpdateResponse,
)
from taf.gnb.oam.coam.vdu.schemas.asm_licensed.rad_domain_response import (
    RadDomainResponse,
)
from taf.gnb.oam.coam.vdu.schemas.asm_licensed.rad_params_response import (
    RadParamsResponse,
)
from taf.gnb.oam.coam.vdu.schemas.emservice_licensed.nms_resp_v1 import NMSRespV1
from taf.gnb.oam.coam.vdu.schemas.fh.ald_selection_mode_info import AldSelectionModeInfo
from taf.gnb.oam.coam.vdu.schemas.fh.get_rmods_syncinfolist import RmodsSyncInfo
from taf.gnb.oam.coam.vdu.schemas.fh.get_trigger_ald_response import (
    GetTriggerAldResponse,
)
from taf.gnb.oam.coam.vdu.services.emservice_licensed.emservice_licensed_v1 import (
    EMServiceLicensedv1,
)
from taf.gnb.oam.coam.vdu.services.pm_licensed.pm_licensed_v1 import PMLICENSEDv1
from taf.gnb.oam.coam.vdu.utilities.use_m2m_parser import enforce_use_m2m_type


class vDuOAM23R2(vDuOAM23R1):
    def __init__(self, con_details, need_all_info=False):
        super(vDuOAM23R2, self).__init__(con_details, need_all_info)
        self.em_service_licensed_v1 = EMServiceLicensedv1(con_details=con_details)
        self.pm_licensed_v1 = PMLICENSEDv1(con_details=con_details)

    @enforce_use_m2m_type
    def get_nms(self, timeout=30):
        response = self.em_service_licensed_v1.get_nms(timeout=timeout)
        return NMSRespV1.from_object_dict(response)

    def get_network_slicing(self, timeout=30):
        response = self.asm_v1.get_network_slicing(timeout=timeout).created
        return list(map(NetworkSlicing.from_object_dict, response))

    def lock_network_slicing(self, network_slicing_ids, timeout=30, raw=False):
        response = self.asm_v1.lock_network_slicing(network_slicing_ids=network_slicing_ids, timeout=timeout)
        return response if raw else LockSlicingOperationRespV1.from_object_dict(response)

    def get_operate_network_slicing_state(self, operation_id, timeout=30):
        response = self.asm_v1.get_operate_network_slicing_state(operation_id=operation_id, timeout=timeout)
        return LockSlicingOperationRespV1.from_object_dict(response)

    def unlock_network_slicing(self, network_slicing_ids, timeout=30, raw=False):
        response = self.asm_v1.unlock_network_slicing(network_slicing_ids=network_slicing_ids, timeout=timeout)
        return response if raw else LockSlicingOperationRespV1.from_object_dict(response)

    @enforce_use_m2m_type
    def get_alds(self, timeout=30, raw=False):
        response = self.asm_licensed.get_alds(timeout=timeout)
        return response if raw else GetAldsResponseV1.from_object_dict(response)

    def get_rets_information(self, timeout=30):
        response = self.asm_v1.get_rets_information(timeout=timeout).created
        return list(map(GetRETsDiffV1.from_object_dict, response))

    def get_mhas_information(self, timeout=30):
        response = self.asm_v1.get_mhas_information(timeout=timeout).created
        return list(map(GetMHAsDiffV1.from_object_dict, response))

    def get_raes_information(self, timeout=30):
        response = self.asm_v1.get_raes_information(timeout=timeout).created
        return list(map(GetRAEsDiffV1.from_object_dict, response))

    @enforce_use_m2m_type
    def get_alds_selection_mode(self, timeout=30, use_m2m=True, raw=False):
        if use_m2m:
            response = self.fh_licensed_v1.get_alds_selection_mode(timeout=timeout)
        else:
            response = self.fh_v1.get_alds_selection_mode(timeout=timeout)
        return response if raw else AldSelectionModeInfo.from_object_dict(response)

    @enforce_use_m2m_type
    def get_ald_select_mode_operation_status(self, operation_id, timeout=30, use_m2m=True, raw=False):
        if use_m2m:
            response = self.fh_licensed_v1.get_ald_select_mode_operation_status(operation_id=operation_id,
                                                                                timeout=timeout)
        else:
            response = self.fh_v1.get_ald_select_mode_operation_status(operation_id=operation_id, timeout=timeout)
        return response if raw else GetTriggerAldResponse.from_object_dict(response)

    @enforce_use_m2m_type
    def trigger_ald_selection_mode(self, ald_selection_mode, timeout=30, use_m2m=True, raw=False):
        if use_m2m:
            response = self.fh_licensed_v1.trigger_ald_selection_mode(ald_selection_mode=ald_selection_mode,
                                                                      timeout=timeout)
        else:
            response = self.fh_v1.trigger_ald_selection_mode(ald_selection_mode=ald_selection_mode,
                                                             timeout=timeout)
        return response if raw else GetTriggerAldResponse.from_object_dict(response)

    def get_rad_debug_params_summary(self, timeout=30):
        return self.asm_v1.get_rad_debug_params_summary(timeout=timeout).has_non_default_param

    @enforce_use_m2m_type
    def rad_reload_domains(self, timeout=30, use_m2m=True):
        if use_m2m:
            response = self.asm_licensed.rad_reload_domains(timeout=timeout)
        else:
            response = self.asm_v1.rad_reload_domains(timeout=timeout)
        return RadDomainResponse.from_object_dict(response)

    @enforce_use_m2m_type
    def get_reload_domains_operation(self, operation_id, timeout=30, use_m2m=True):
        if use_m2m:
            response = self.asm_licensed.get_reload_domains_operation(operation_id=operation_id, timeout=timeout)
        else:
            response = self.asm_v1.get_reload_domains_operation(operation_id=operation_id, timeout=timeout)
        return RadDomainResponse.from_object_dict(response)

    @enforce_use_m2m_type
    def rad_reload_params(self, domain_name=None, param_name=None, non_default_only=False, timeout=30, use_m2m=True):
        if use_m2m:
            response = self.asm_licensed.rad_reload_params(domain_name=domain_name,
                                                           param_name=param_name,
                                                           non_default_only=non_default_only,
                                                           timeout=timeout)
        else:
            response = self.asm_v1.rad_reload_params(domain_name=domain_name,
                                                     param_name=param_name,
                                                     non_default_only=non_default_only,
                                                     timeout=timeout)
        return RadParamsResponse.from_object_dict(response)

    @enforce_use_m2m_type
    def get_reload_params_operation(self, operation_id, timeout=30, use_m2m=True):
        if use_m2m:
            response = self.asm_licensed.get_reload_params_operation(operation_id=operation_id, timeout=timeout)
        else:
            response = self.asm_v1.get_reload_params_operation(operation_id=operation_id, timeout=timeout)
        return RadParamsResponse.from_object_dict(response)

    @enforce_use_m2m_type
    def update_rad_debug_params(self, persistency=None, domain_name=None, parameters=None, node_id=None, timeout=30,
                                use_m2m=True):
        if use_m2m:
            response = self.asm_licensed.update_rad_debug_params(persistency=persistency, node_id=node_id,
                                                                 domain_name=domain_name, parameters=parameters,
                                                                 timeout=timeout)
        else:
            response = self.asm_v1.update_rad_debug_params(persistency=persistency,
                                                           node_id=node_id,
                                                           domain_name=domain_name,
                                                           parameters=parameters,
                                                           timeout=timeout)
        return RadDebugParamUpdateResponse.from_object_dict(response)

    @enforce_use_m2m_type
    def get_rad_debug_params_update_operation(self, operation_id, timeout=30, use_m2m=True):
        if use_m2m:
            response = self.asm_licensed.get_rad_debug_params_update_operation(operation_id=operation_id,
                                                                               timeout=timeout)
        else:
            response = self.asm_v1.get_rad_debug_params_update_operation(operation_id=operation_id, timeout=timeout)
        return RadDebugParamUpdateResponse.from_object_dict(response)

    @enforce_use_m2m_type
    def cancel_snapshot_operation(self, operation_id, timeout=30, is_local=True, use_m2m=True, directory=None):
        if use_m2m:
            response = self.asm_licensed.cancel_snapshot_operation(operation_id=operation_id,
                                                                   timeout=timeout,
                                                                   directory=directory)
        else:
            if is_local:
                response = self.asm_v1.cancel_local_snapshot_operation(operation_id=operation_id,
                                                                       timeout=timeout,
                                                                       directory=directory)
            else:
                response = self.asm_v1.cancel_remote_snapshot_operation(operation_id=operation_id, timeout=timeout)
        return response

    def revert_managed_object(self, plan_id, mo_uuid, include_children=False, timeout=30):
        return self.asm_v1.revert_managed_object(plan_id=plan_id,
                                                 mo_uuid=mo_uuid,
                                                 include_children=include_children,
                                                 timeout=timeout)

    def get_revert_managed_object_action(self, plan_id, action_id, timeout=30):
        response = self.asm_v1.get_revert_managed_object_action(plan_id=plan_id, action_id=action_id, timeout=timeout)
        return RevertObjectResponseV1.from_object_dict(response)

    def get_rmods_syncinfolist(self, timeout=30):
        response = self.fh_licensed_v1.get_rmods_syncinfolist(timeout=timeout)
        return list(map(RmodsSyncInfo.from_object_dict, response))

    def vdu_get_all_raw_measurement_data(self, timeout=30):
        return self.pm_licensed_v1.vdu_get_all_raw_measurement_data(timeout=timeout)
